/// Food imagery. The seeded API ships no photographs (image_asset is null),
/// so this renders INTENTIONAL original placeholder art (generated by
/// scripts/generate_food_images.py — no third-party photography) picked
/// deterministically from the item's id, plus an initials avatar for
/// restaurants. If the API ever provides `imageAsset`, that asset wins.
library;

import 'package:flutter/material.dart';

import '../../app/theme/app_colors.dart';

const List<String> _dishAssets = [
  'assets/images/dish_biryani.png',
  'assets/images/dish_pizza.png',
  'assets/images/dish_salad.png',
  'assets/images/dish_burger.png',
  'assets/images/dish_pasta.png',
  'assets/images/dish_dessert.png',
  'assets/images/dish_chicken.png',
  'assets/images/dish_soup.png',
  'assets/images/dish_sushi.png',
  'assets/images/dish_smoothie.png',
];

/// Stable non-negative hash (not dart:core identity — deterministic across
/// platforms/runs so the same item always renders the same tile).
int stableHash(String value) {
  var hash = 0;
  for (final rune in value.runes) {
    hash = (hash * 31 + rune) & 0x7fffffff;
  }
  return hash;
}

class FoodImage extends StatelessWidget {
  const FoodImage({
    super.key,
    required this.itemId,
    this.assetName,
    this.size = 64,
    this.rounded = true,
    this.roundedRadius = AppSpacing.radiusMd,
    this.expand = false,
  });

  final String itemId;
  final String? assetName;
  final double size;
  final bool rounded;
  final double roundedRadius;

  /// Fill the parent's box instead of a fixed [size] square (menu tiles).
  final bool expand;

  @override
  Widget build(BuildContext context) {
    final asset = (assetName != null && assetName!.isNotEmpty && assetName!.startsWith('assets/'))
        ? assetName!
        : _dishAssets[stableHash(itemId) % _dishAssets.length];
    final image = Image.asset(
      asset,
      width: expand ? null : size,
      height: expand ? null : size,
      fit: BoxFit.cover,
      filterQuality: FilterQuality.medium,
      errorBuilder: (_, _, _) => expand
          ? _FallbackFill(seed: itemId)
          : _FallbackTile(size: size, seed: itemId),
    );
    return ClipRRect(
      borderRadius: BorderRadius.circular(rounded ? roundedRadius : AppSpacing.radiusPill),
      child: expand ? SizedBox.expand(child: image) : image,
    );
  }
}

/// Expanding fallback for tiles whose box is sized by the parent.
class _FallbackFill extends StatelessWidget {
  const _FallbackFill({required this.seed});

  final String seed;

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [
            AppColors.primaryTint,
            AppColors.peach,
            AppColors.surfaceWarm,
          ],
          stops: const [0.0, 0.5, 1.0],
          transform: _GradientRotation((stableHash(seed) % 360) * 3.14159 / 180),
        ),
      ),
      child: const Center(
        child: Icon(
          Icons.restaurant_rounded,
          color: AppColors.primary,
          size: 32,
        ),
      ),
    );
  }
}

class _FallbackTile extends StatelessWidget {
  const _FallbackTile({required this.size, required this.seed});

  final double size;
  final String seed;

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [
            AppColors.primaryTint,
            AppColors.peach,
            AppColors.surfaceWarm,
          ],
          stops: const [0.0, 0.5, 1.0],
          transform: _GradientRotation((stableHash(seed) % 360) * 3.14159 / 180),
        ),
        borderRadius: BorderRadius.circular(AppSpacing.radiusMd),
      ),
      child: const Icon(
        Icons.restaurant_rounded,
        color: AppColors.primary,
        size: 28,
      ),
    );
  }
}

class _GradientRotation extends GradientTransform {
  const _GradientRotation(this.radians);

  final double radians;

  @override
  Matrix4 transform(Rect bounds, {TextDirection? textDirection}) =>
      Matrix4.rotationZ(radians);
}

/// Restaurant initials avatar (restaurants have no photographs in the API).
class RestaurantAvatar extends StatelessWidget {
  const RestaurantAvatar({super.key, required this.name, this.size = 56});

  final String name;
  final double size;

  String get _initials {
    final words = name.trim().split(RegExp(r'\s+')).take(2);
    return words.map((word) => word.isEmpty ? '' : word[0].toUpperCase()).join();
  }

  static const List<Color> _palette = [
    Color(0xFFDB3A1F),
    Color(0xFFB25E2C),
    Color(0xFF7A5C2E),
    Color(0xFF237A46),
    Color(0xFF1F6A8A),
    Color(0xFF8A3E6B),
  ];

  @override
  Widget build(BuildContext context) {
    final color = _palette[stableHash(name) % _palette.length];
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.14),
        shape: BoxShape.circle,
        border: Border.all(color: color.withValues(alpha: 0.35)),
      ),
      alignment: Alignment.center,
      child: Text(
        _initials,
        style: TextStyle(
          color: color,
          fontWeight: FontWeight.w800,
          fontSize: size * 0.34,
          letterSpacing: 0.5,
        ),
      ),
    );
  }
}
